// Recupera o estado salvo (se existir)
let state = {};
try {
  const saved = $input.item.json.state;
  if (saved) state = typeof saved === 'string' ? JSON.parse(saved) : saved;
} catch (e) {
  state = {};
}

const msg = ($input.item.json.message_text || '').trim();
const msgLower = msg.toLowerCase();
const startKeywords = ['oi', 'olá', '/start', 'start'];
const isStart = startKeywords.includes(msgLower);

// Reinicia fluxo quando usuário pede ou quando não há estado prévio
if (isStart || !state.step) {
  state = { chat_id: $input.item.json.chat_id, user_name: $input.item.json.user_first_name, step: 0, data: {}, attempts: 0 };
}

const output = { action: 'ask', text: '', state };

// Passo 0 - Saudação
if (state.step === 0) {
  output.text = `👋 Olá, ${state.user_name}! Sou seu assistente jurídico e vou te ajudar a ver o status do seu processo.

Para começar, me informe seu *Nome Completo*:`;
  state.step = 1;
  return { json: output };
}

// Passo 1 - Nome completo
if (state.step === 1) {
  if (msg.length < 5 || !msg.includes(' ')) {
    output.text = '⚠️ Preciso do nome completo, com nome e sobrenome. Pode enviar novamente?';
    return { json: output };
  }
  state.data.nome = msg;
  state.step = 2;
  output.text = `Obrigada, ${msg.split(' ')[0]}!

Agora preciso da sua *Data de Nascimento* no formato DD/MM/AAAA (ex: 15/05/1990):`;
  return { json: output };
}

// Passo 2 - Data de nascimento
if (state.step === 2) {
  const dateRegex = /^(0[1-9]|[12][0-9]|3[01])/(0[1-9]|1[0-2])/(19|20)\d{2}$/;
  if (!dateRegex.test(msg)) {
    output.text = '⚠️ Formato inválido. Use DD/MM/AAAA (ex: 08/11/1989). Tente de novo:';
    return { json: output };
  }
  state.data.nascimento = msg;
  state.step = 3;
  output.text = 'Anotado! Qual o nome completo do *Advogado(a)* responsável pelo processo?';
  return { json: output };
}

// Passo 3 - Nome do advogado
if (state.step === 3) {
  if (msg.length < 5) {
    output.text = '⚠️ O nome do advogado parece curto. Confirme o nome completo, por favor:';
    return { json: output };
  }
  state.data.advogado = msg;
  state.step = 4;
  output.text = 'Perfeito! Agora digite o *Número do Processo* no padrão CNJ (20 dígitos). Pode enviar com ou sem pontos e traços:';
  return { json: output };
}

// Passo 4 - Número do processo
if (state.step === 4) {
  const cleanNum = msg.replace(/[^0-9]/g, '');
  const cnjRegex = /^\d{20}$/;
  if (!cnjRegex.test(cleanNum)) {
    output.text = '⚠️ O número deve ter 20 dígitos. Confira e envie novamente (ex: 0001234-56.2023.8.09.0001):';
    return { json: output };
  }

  state.data.numero_processo = cleanNum;
  state.data.numero_formatado = `${cleanNum.slice(0,7)}-${cleanNum.slice(7,9)}.${cleanNum.slice(9,13)}.${cleanNum.slice(13,14)}.${cleanNum.slice(14,16)}.${cleanNum.slice(16,20)}`;
  state.step = 5;

  output.text = '⏳ Entendido! Vou consultar os tribunais agora. Só um instante...';
  output.action = 'search';
  return { json: output };
}

output.text = 'Não entendi. Digite /start para recomeçar ou envie um Oi para reiniciar.';
return { json: output };

