const codigoJustica = num.substring(13, 15);

const map = {
  '90': 'tst', '88': 'tse', '10': 'stj', '11': 'stm',
  '01': 'trf1', '02': 'trf2', '03': 'trf3', '04': 'trf4', '05': 'trf5', '06': 'trf6',
